Identify the sorting algorithm implemented by the following code:
void f(int x[], int n)
{
Int i,j,temp;
for(i=0; i<n; i++)
{
for(j=0; j<(n-i-1); j++)
{
if (x[j] > x[j+1])
{
temp = x[j];
x[j]
= x[j+1];
x[j+1] = temp;
}
}
}
}

