What is the output of the following 'C' code snippet?

#include <stdio.h>
void tchange(int* b, int* a) {
    *a += *a;
    *b *= *a;
    *a++ = ++*b;
    *--b = *--a;
}
void main() {
    int a = 2, b = 5;
    tchange(&a, &b);
    printf("%d %d", a, b);
}

